import requests

TI_URL = "https://ti.example.com/api/v1/ip/"

def enrich(alert):
    ip = alert["src_ip"]
    r = requests.get(TI_URL + ip, headers={"X-Api-Key": TI_KEY}, timeout=5)
    if r.status_code != 200:
        return {"reputation": "clean"}
    return {"reputation": r.json().get("verdict", "unknown")}

